  Proof.
    intros until r. intros HH3 HCS3 ET3 ES3 SP1 SP1M F64 FRSH FRSH3 CFB AP FHD MPB RPB FSH SAVE SLOT ST24 SThi STlo MI PRES CX OX XAL X0 APX XS WCX HR LIM.
    rt_facts.
    pose proof (hcs_ok asegs R HIA h3) as CSOK3.
    pose proof (hm_top asegs R HIA h3 _ _ _ HH3) as HTOP3. rewrite ET3, ES3 in HTOP3.
    assert (SP1R : 0 <= sp1 < 2^64) by (clear - SP1 SPR SLO LOS ALO ACV NEEDR NER; lia).
    assert (CFB3 : crange (hcs asegs R HIA h3) FB 256) by (eapply crange_mono; [exact HCS3| exact CFB]).
    assert (SCS : crange CS lo (bv_unsigned sp - lo)) by (eapply crange_sub; [exact SCS0| clear - LOS; lia| clear - SLO NEEDR NER TOP HTOP3; lia]).
    assert (SCS3 : crange (hcs asegs R HIA h3) lo (bv_unsigned sp - lo)) by (eapply crange_mono; [exact HCS3| exact SCS]).
    assert (SCS03 : crange (hcs asegs R HIA h3) (arl_stklo R) (hstkhi asegs R HIA h - arl_stklo R)) by (eapply crange_mono; [exact HCS3| exact SCS0]).
    destruct (frame_factsA R HIA (hcs asegs R HIA h3) h3 LBb LF mm FB 256 lo HH3 eq_refl FRSH3 F64 ltac:(clear; lia) ltac:(reflexivity) LOS)
      as (_ & INF & INH3 & IND3 & _ & _ & F8 & FBLO & SBND & APS). change (256 / 8) with 32 in SBND, APS. change (256 - 40) with 216 in IND3.
    pose proof FRSH as FRSH'. unfold fresh_apart in FRSH'. destruct FRSH' as (F0 & F1 & F2 & F3).
    pose proof (art_stk_high asegs R HIA) as STKH.
    pose proof (hm_wlow asegs R HIA h3 _ _ _ HH3) as WL3.
    assert (WLa : wlow R LBa LF) by (split; [exact (proj2 (proj2 (proj2 PRES)))| apply (art_data_lo asegs R HIA)]).
    assert (XS1 : X + 16 <= lo \/ sp1 <= X) by (clear - XS SP1; lia).
    assert (RPFB : A_RP_P256K1 + 8 <= FB \/ FB + 256 <= A_RP_P256K1).
    { destruct (hm_apart asegs R HIA h3 _ _ _ HH3) as [HBRq _]. rewrite Forall_forall in HBRq.
      destruct (HBRq (FB, 256) ltac:(apply in_app_iff; right; left; reflexivity)) as (_ & _ & _ & KI). cbn [fst snd] in KI.
      assert (PR : forall a, A_RP_P256K1 <= a < A_RP_P256K1 + 8 -> rtc_prist a).
      { intros a Ha. unfold rtc_prist, rtc_pristine. do 2 apply Exists_cons_tl. apply Exists_cons_hd. cbn [fst snd]. unfold A_RP_P256K1 in Ha. clear - Ha. lia. }
      pose proof (PRIMG _ (PR A_RP_P256K1 ltac:(clear; lia))) as K1. pose proof (PRIMG _ (PR (A_RP_P256K1 + 7) ltac:(clear; lia))) as K2. clear - KI K1 K2. lia. }
    pose proof (rw_cells_bound _ _ _ _ CX) as XB. unfold mpi_cells in XB, CX. cbn [cells_size csize Nat.add] in XB.
    (* [comment removed for export] *)
    zstep. if_cases KR; zify_cond KR.
    { assert (RNZ : r <> 0) by (intros C; apply KR; rewrite C; reflexivity).
      apply evtA_done. unfold MIDQ. exists mm, xs3. do 24 eexists.
      split; [reflexivity|].
      split; [exact HH3|]. split; [exact FHD|]. split; [exact FSH|]. split; [exact SAVE|]. split; [exact SLOT|]. split; [exact ST24|]. split; [exact SThi|].
      split; [exact STlo|]. split; [exact MI|]. split; [exact PRES|]. split; [exact CX|].
      split; [intros C; exfalso; exact (RNZ C)| intros _; reflexivity]. }
    assert (R0 : r = 0).
    { destruct (Z.eq_dec r 0) as [E|NE]; [exact E| exfalso].
      clear - KR HR NE. assert (r mod 18446744073709551616 = r + 18446744073709551616) by (symmetry; apply (Z.mod_unique r 18446744073709551616 (-1)); lia). lia. }
    subst r. clear KR.
    destruct (LIM eq_refl) as (N16 & XIN & PAL & P0 & XARR & LENX & FRX & XPS). clear LIM.
    pose proof LENX as LENX0.
    pose proof FRX as FRX'. unfold fresh_apart in FRX'. destruct FRX' as (FX0 & FX1 & FX2 & FX3).
    assert (OP : aobj asegs AL (hcs asegs R HIA h3) mm p3 (4 * n3)) by (eapply hm_aobj_block; [exact HH3| exact XIN]).
    assert (CWP : client_wrange L (LBb ++ fdata ((FB, 256) :: LF)) (arl_stklo R) (htop asegs R HIA h3) p3 (4 * n3))
      by (eapply client_wrange_block; [apply in_or_app; left; exact XIN| clear; lia| clear; lia]).
    assert (PFB : FB + 256 <= p3 \/ p3 + 4 * n3 <= FB).
    { destruct FRSH3 as (_ & _ & _ & G3). pose proof (G3 _ _ ltac:(apply in_app_iff; left; exact XIN)) as K. clear - K. lia. }
    assert (WCP : wcover R LBa LF (bv_unsigned sp) WA p3 (4 * n3)) by (eapply wcover_fresh; [exact FRX| clear; lia| clear; lia| clear - LOS SLO ALO NER NEEDR; lia]).
    (* [comment removed for export] *)
    assert (XSH : forall ma m' ws, u32arr asegs ma p3 ws -> Z.of_nat (length ws) = n3 -> munch [(Z.shiftr FB 3 + al_sb AL, Z.shiftr FB 3 + al_sb AL + 32)] ma m' -> wmono asegs ma m' -> u32arr asegs m' p3 ws)
      by (intros ma m' ws HA HL MUq WMq; eapply (u32arr_transport asegs); [exact HA| exact MUq| exact WMq|]; rewrite HL; cbn [disjoint_from fst snd]; split; [| exact I];
          pose proof (apart_client_shadow AL (hcs asegs R HIA h3) p3 (4 * n3) FB (Z.shiftr FB 3 + al_sb AL) 32 CSOK3 ltac:(eapply aobj_crange; exact OP) CFB3 ltac:(shadow_addr_eq) ltac:(clear - N16; lia) ltac:(clear; lia)) as K; clear - K; lia).
    (* [comment removed for export] *)
    do 8 zstep.
    (* [comment removed for export] *)
    pose proof (munch_refl [(Z.shiftr FB 3 + al_sb AL, Z.shiftr FB 3 + al_sb AL + 32)] mm) as MUs. pose proof (wmono_refl asegs mm) as WMs.
    pose proof (conj XARR I) as XARRb. clear XARR.
    do 9 zstep.
    match goal with H : rw_cells _ _ (Z.shiftr FB 3 + al_sb AL) _ |- _ => norm_b8 H; rename H into FSH2 end.
    destruct XARRb as [XARR _]. apply (XSH _ _ _ XARR LENX MUs) in WMs. clear XARR MUs. rename WMs into XARR.
    lazymatch goal with |- _ (MS _ _ _ _ _ ?mx _) => rename mx into m4 end.
    frame_aobj FSH2 (FB + 96) 5%nat as ORP.
    (* [comment removed for export] *)
    lx_mkR. pose proof (arl_need_rt_amem R) as LXNRA.
    frame_aobj FSH2 (FB + 32) 4%nat as OM.
    pose proof (cells_at_wf _ _ _ _ (proj1 MPB)) as WF. cbn [cells_wf cell_wf] in WF. destruct WF as [LJM _].
    pose proof (cells_at_wf _ _ _ _ (proj1 RPB)) as WF. cbn [cells_wf cell_wf] in WF. destruct WF as [LJR _].
    apply (u8arr_of_rw_cells asegs) in MPB. apply (u8arr_of_rw_cells asegs) in RPB.
    destruct (MpiWalkAux.u32arr_of_u8arr asegs m4 (FB + 32) _ 8 MPB ltac:(rewrite LJM; reflexivity)) as (ml0 & MARR & LENM0).
    destruct (MpiWalkAux.u32arr_of_u8arr asegs m4 (FB + 96) _ 10 RPB ltac:(rewrite LJR; reflexivity)) as (rl0 & RARR & LENR0).
    assert (LENM : Z.of_nat (length ml0) = 8) by (rewrite LENM0; reflexivity). assert (LENR : Z.of_nat (length rl0) = 10) by (rewrite LENR0; reflexivity).
    clear MPB RPB LENM0 LENR0 LJM LJR.
    assert (RPBY : bytes_at asegs m4 A_RP_P256K1 (u32s [Z_to_bv 64 0x3d1; Z_to_bv 64 0x1])).
    { pose proof (asan_rtc_const m4 A_RP_P256K1 (u32s [Z_to_bv 64 0x3d1; Z_to_bv 64 0x1]) (RTC m4 (hm_rtc asegs R HIA h3 _ _ m4 HH3)) ltac:(vm_compute; reflexivity) ltac:(vm_compute; reflexivity)) as RO.
      destruct RO as [_ Hb]. cbn [cells_bytes cbytes] in Hb. rewrite app_nil_r in Hb. exact Hb. }
    assert (ORPI : aobj asegs AL (hcs asegs R HIA h3) m4 A_RP_P256K1 8).
    { eapply (AImgGlobals.aobj_img asegs AL); [apply (A_mpi_copy.hcs_img_cs_cp R HIA IMG)| eapply (hm_img_shadow asegs R HIA); exact HH3| vm_compute; reflexivity]. }
    assert (RPX : A_RP_P256K1 + 8 <= p3 \/ p3 + 4 * n3 <= A_RP_P256K1).
    { destruct (hm_apart asegs R HIA h3 _ _ _ HH3) as [HBRq _]. rewrite Forall_forall in HBRq.
      destruct (HBRq (p3, 4 * n3) ltac:(apply in_app_iff; left; exact XIN)) as (_ & _ & _ & KI). cbn [fst snd] in KI.
      assert (PR : forall a, A_RP_P256K1 <= a < A_RP_P256K1 + 8 -> rtc_prist a).
      { intros a Ha. unfold rtc_prist, rtc_pristine. do 2 apply Exists_cons_tl. apply Exists_cons_hd. cbn [fst snd]. unfold A_RP_P256K1 in Ha. clear - Ha. lia. }
      pose proof (PRIMG _ (PR A_RP_P256K1 ltac:(clear; lia))) as K1. pose proof (PRIMG _ (PR (A_RP_P256K1 + 7) ltac:(clear; lia))) as K2. clear - KI K1 K2. unfold A_RP_P256K1 in *. lia. }
    unfold A_RP_P256K1 in RPBY, ORPI, RPX, RPFB.
    (* [comment removed for export] *)
    lazymatch type of RPBY with bytes_at _ _ _ (u32s ?l) =>
      remember l as lxrp eqn:LXERP in RPBY; assert (LENRP : Z.of_nat (length lxrp) = 2) by (rewrite LXERP; reflexivity); clear LXERP end.
    pose proof (hm_abase asegs R HIA h3 _ _ m4 HH3) as ABm. pose (lxi := lxA_img (arl_AL R) IMG).
    assert (CW_1 : client_wrange L (LBb ++ fdata ((FB, 256) :: LF)) (arl_stklo R) (htop asegs R HIA h3) (FB + 32) (4 * 8)) by (eapply client_wrange_block; [exact IND3| clear; lia| clear; lia]).
    assert (CW_2 : client_wrange L (LBb ++ fdata ((FB, 256) :: LF)) (arl_stklo R) (htop asegs R HIA h3) (FB + 96) (4 * 10)) by (eapply client_wrange_block; [exact IND3| clear; lia| clear; lia]).
    assert (SFF : shadow_free R LBa LF (arl_stklo R) (hstkhi asegs R HIA h3) FB 256)
      by (eapply shadow_free_fresh; [exact FRSH | exact (proj2 (proj2 (proj2 PRES))) | clear; lia | clear; lia | exact ALO | exact AP]).
    lx_pre. lxe_pose. lxe_sums [SUM_amemsetWinA 4 5; SUM_amemsetWinA 6 7; SUM_amemsetWinA 8 9; SUM_amemcpyWinA 4 6 5; SUM_amemcpyWinA 4 8 5; SUM_amemcpyWinA 6 4 7; SUM_amemcpyWinA 6 8 7; SUM_amemcpyWinA 8 4 9; SUM_amemcpyWinA 8 6 9; SUM_coreaddXXBA; SUM_coremulA 8 9] [p3; n3; FB + 32; 8; FB + 96; 10].
    lx_pre. lx_run_tac (PLANS [0xd3c78] [(0xd3b18, DJoin)] 1000%N [SUM_amemsetWinA 4 5; SUM_amemsetWinA 6 7; SUM_amemsetWinA 8 9; SUM_amemcpyWinA 4 6 5; SUM_amemcpyWinA 4 8 5; SUM_amemcpyWinA 6 4 7; SUM_amemcpyWinA 6 8 7; SUM_amemcpyWinA 8 4 9; SUM_amemcpyWinA 8 6 9; SUM_coreaddXXBA; SUM_coremulA 8 9]). lx_tree.
    all: lxr_leaf; lxe_leaf_gc.
    (* [comment removed for export] *)
    apply evtA_done. unfold MIDQ.
    lazymatch goal with H : u32arr asegs ?mx p3 ?l |- context [MS _ _ _ _ _ ?mx _] => exists mx, l end. do 24 eexists.
    split; [reflexivity|].
    repeat (split; [eassumption|]).
    split; [ intros _; split; [ eassumption
                              | lazymatch goal with HL : Z.of_nat (length ?l) = _ |- length ?l = _ =>
                                  rewrite ?upd_length in HL; rewrite ?upd_length; clear - HL LENX0; lia end ]
           | intros C; exfalso; apply C; reflexivity ].
    all: match goal with |- ?g => idtac "MID-LEFT:" g end.
  Qed.

